72	static inline V4 cas_asc_adj(V4 v) {
73	    const D4 d4;
74	    V4 rv = hn::Reverse2(d4, v);                 // [b,a,d,c]
75	    V4 lo = hn::Min(v, rv), hi = hn::Max(v, rv); // both symmetric
76	    return hn::OddEven(hi, lo);                   // [min,max,min,max]
77	}
78	
79	static inline V4 cas_desc_adj(V4 v) {
80	    const D4 d4;
81	    V4 rv = hn::Reverse2(d4, v);
82	    V4 lo = hn::Min(v, rv), hi = hn::Max(v, rv);
83	    return hn::OddEven(lo, hi);                   // [max,min,max,min]
84	}
