86	// Lower pair ascending, upper pair descending: [min01, max01, max23, min23]
87	static inline V4 cas_mixed_adj(V4 v) {
88	    const D4 d4; const D2 d2;
89	    V4 rv = hn::Reverse2(d4, v);
90	    V4 lo = hn::Min(v, rv), hi = hn::Max(v, rv);
91	    V4 asc  = hn::OddEven(hi, lo);               // [min01,max01,min23,max23]
92	    V4 desc = hn::OddEven(lo, hi);               // [max01,min01,max23,min23]
93	    V2 asc_lo  = hn::LowerHalf(asc);             // [min01, max01]
94	    V2 desc_hi = hn::UpperHalf(d2, desc);        // [max23, min23]
95	    return hn::Combine(d4, desc_hi, asc_lo);
96	}
