99	static inline V4 cas_asc_skip2(V4 v) {
100	    const D4 d4; const D2 d2;
101	    V4 rv = hn::CombineShiftRightBytes<8>(d4, v, v);  // [c,d,a,b]
102	    V4 lo = hn::Min(v, rv), hi = hn::Max(v, rv);       // symmetric
103	    return hn::Combine(d4, hn::UpperHalf(d2, hi), hn::LowerHalf(lo));
104	}
