118	void bitonic_sort_highway(int* a) {
119	    const D4 d4;
120	    V4 v0 = hn::Load(d4, a);
121	    V4 v1 = hn::Load(d4, a + 4);
122	    V4 v2 = hn::Load(d4, a + 8);
123	    V4 v3 = hn::Load(d4, a + 12);
124	
125	    // ---- Phase 1 (k=2): sort pairs, alternating ↑↓ ----
126	    // Step 1: (0,1)↑(2,3)↓ in each register
127	    v0 = cas_mixed_adj(v0);
128	    v1 = cas_mixed_adj(v1);
129	    v2 = cas_mixed_adj(v2);
130	    v3 = cas_mixed_adj(v3);
131	
132	    // ---- Phase 2 (k=4): build sorted 4-element runs ----
133	    // Step 2: stride-2  — v0,v2 ascending; v1,v3 descending
134	    v0 = cas_asc_skip2(v0);    v1 = cas_desc_skip2(v1);
135	    v2 = cas_asc_skip2(v2);    v3 = cas_desc_skip2(v3);
136	
137	    // Step 3: adjacent — v0,v2 ascending; v1,v3 descending
138	    v0 = cas_asc_adj(v0);      v1 = cas_desc_adj(v1);
139	    v2 = cas_asc_adj(v2);      v3 = cas_desc_adj(v3);
140	
141	    // ---- Phase 3 (k=8): build sorted 8-element runs ----
142	    // Step 4: cross-register  (v0,v1)↑  (v2,v3)↓
143	    { V4 t = hn::Min(v0,v1); v1 = hn::Max(v0,v1); v0 = t; }
144	    { V4 t = hn::Max(v2,v3); v3 = hn::Min(v2,v3); v2 = t; }
145	
146	    // Step 5: stride-2 — v0,v1 ascending; v2,v3 descending
147	    v0 = cas_asc_skip2(v0);    v1 = cas_asc_skip2(v1);
148	    v2 = cas_desc_skip2(v2);   v3 = cas_desc_skip2(v3);
149	
150	    // Step 6: adjacent — v0,v1 ascending; v2,v3 descending
151	    v0 = cas_asc_adj(v0);      v1 = cas_asc_adj(v1);
152	    v2 = cas_desc_adj(v2);     v3 = cas_desc_adj(v3);
153	
154	    // ---- Phase 4 (k=16): final merge, all ascending ----
155	    // Step 7: cross-register  (v0,v2)↑  (v1,v3)↑
156	    { V4 t = hn::Min(v0,v2); v2 = hn::Max(v0,v2); v0 = t; }
157	    { V4 t = hn::Min(v1,v3); v3 = hn::Max(v1,v3); v1 = t; }
158	
159	    // Step 8: cross-register  (v0,v1)↑  (v2,v3)↑
160	    { V4 t = hn::Min(v0,v1); v1 = hn::Max(v0,v1); v0 = t; }
161	    { V4 t = hn::Min(v2,v3); v3 = hn::Max(v2,v3); v2 = t; }
162	
163	    // Step 9: stride-2 all ascending
164	    v0 = cas_asc_skip2(v0);    v1 = cas_asc_skip2(v1);
165	    v2 = cas_asc_skip2(v2);    v3 = cas_asc_skip2(v3);
166	
167	    // Step 10: adjacent all ascending
168	    v0 = cas_asc_adj(v0);      v1 = cas_asc_adj(v1);
169	    v2 = cas_asc_adj(v2);      v3 = cas_asc_adj(v3);
170	
171	    hn::Store(v0, d4, a);
172	    hn::Store(v1, d4, a + 4);
173	    hn::Store(v2, d4, a + 8);
174	    hn::Store(v3, d4, a + 12);
175	}
