244	template <typename SortFn>
245	double bench_sort_ns(const vector<int>& data, SortFn sort_fn) {
246	    int n = data.size();
247	    int reps = max(1, 100000 / max(n, 1));
248	    vector<vector<int>> copies(RUNS, data);
249	    long long best = LLONG_MAX;
250	    for (int r = 0; r < RUNS; r++) {
251	        auto t0 = high_resolution_clock::now();
252	        for (int k = 0; k < reps; k++) {
253	            copy(data.begin(), data.end(), copies[r].begin());
254	            sort_fn(copies[r]);
255	        }
256	        auto t1 = high_resolution_clock::now();
257	        long long elapsed = duration_cast<nanoseconds>(t1 - t0).count();
258	        best = min(best, elapsed / reps);
259	    }
260	    return (double)best;
261	}
